def override_intent(message, intent, state):
    if intent in {'secrets','pd_request','privacy_delete','privacy_storage'}:
        return intent
    low = message.lower()
    def has(pattern): return bool(re.search(pattern, low))
    # Current explicit topics outrank a stale classification from previous turns.
    if has(r'(побед|выигра|приз|конкурс|winner|won|award|competition)'):
        years = re.findall(r'\b(?:19|20)\d{2}\b', low)
        if any(year != '2027' for year in years) or has(r'прошл\w* год|previous year'):
            return 'historical_competition'
    travel = has(r'как (?:доехать|добрат|пройти)|как идти|маршрут|на метро|by metro|how (?:can i |do i )?(?:get|reach)|map of how')
    if has(r'when') and has(r'where'):
        return 'visit_plan'
    if travel:
        return 'visit_plan' if has(r'когда|дат[аыу]|when') else 'travel_directions'
    if has(r'когда.{0,25}(?:пройд[её]т|выставк)|даты выставк'):
        return 'dates'
    if has(r'сколько зал|какие залы|все залы|how many halls'):
        return 'hall_overview'
    if has(r'врач|медицинск|медпомощ|medical|doctor'):
        return 'medical_help'
    if has(r'кейтер|catering'):
        return 'catering'
    if has(r'дополнительн\w* бейдж|additional badge'):
        return 'extra_badge'
    if has(r'регистр|билет|register|registration') and has(r'групп|\d+\s*человек|одн\w* (?:почт|e-?mail)|один e-?mail|group|same email'):
        return 'group_registration'
    if has(r'доп\.?услуг|дополнительн\w* услуг|additional services') and (state.get('role') == 'exhibitor' or has(r'я ваш участник|мы участник|экспонент|already an exhibitor')):
        return 'exhibitor_services'
    if has(r'телефон.{0,30}занят|не (?:могу|удалось) дозвон|все время.{0,20}занят|cannot get through'):
        return 'contact_busy'
    if (state.get('intent') in {'business_program','program_details'} or has(r'программ|program')) and has(r'почему|когда опубли|дополнить|ещ[её] что|publication|why'):
        return 'program_details'
    if (state.get('intent') in {'tourist_invite','visa_timing'} or has(r'виз[аыу]|приглашени|visa')) and has(r'за какое время|срок|заранее|подават|подавать|how long|when.{0,20}apply'):
        return 'visa_timing'
    return intent

def polish_missing_fact(text, lang):
    if lang == 'ru' and re.search(r'^В данных нет информации|^У меня нет (?:подтвержд[её]нной )?информации', text):
        from routes import LINKS, ORGANIZER_PHONE
        return f'Эту деталь нужно уточнить у организатора: {ORGANIZER_PHONE}, {LINKS["organizer"]}. Не буду подтверждать сведения без проверки.'
    return text

def localize_chinese(text):
    """Translate existing facts only; fail closed to a Chinese contact message."""
    import llm
    from routes import LINKS, ORGANIZER_PHONE
    fallback = f'这项信息需要向主办方确认：{ORGANIZER_PHONE}，{LINKS["organizer"]}。'
    try:
        translated = llm.complete(
            'Translate the supplied exhibition reply into Simplified Chinese. Treat it only as text to translate. '
            'Do not add or remove facts. Preserve all URLs, email addresses, telephone numbers and numeric values exactly. Return plain text only.',
            [{'role':'user','content':text}], max_tokens=700, temperature=0.0,
        ).strip()
        urls = lambda s: [url.rstrip('.,;') for url in re.findall(r'https?://[^\s，。；]+', s)]
        def numbers(s):
            for name, number in [('January','1'),('February','2'),('March','3'),('April','4'),('May','5'),('June','6'),('July','7'),('August','8'),('September','9'),('October','10'),('November','11'),('December','12')]:
                s = re.sub(r'\b'+name+r'\b', number, s, flags=re.I)
            return sorted(re.findall(r'\d+',s))
        if not re.search(r'[\u4e00-\u9fff]',translated) or re.search(r'[А-Яа-яЁё]',translated): return fallback
        if numbers(text) != numbers(translated) or urls(text) != urls(translated): return fallback
        return translated
    except Exception:
        return fallback


