def _normal_company(text):
    return re.sub(r'[^a-zа-яё0-9]+', ' ', text.lower().replace('ё','е')).strip()

def company_matches(message):
    query=set(_normal_company(message).split())
    generic={'ооо','ао','оао','зао','апх','гк','нпо','нпп','завод','группа','компаний','рус','компания','group','company','llc','the'}
    found=[]
    for name,hall,floor in CATALOG_ROWS:
        words=set(_normal_company(name).split())-generic
        if words and any(len(w)>=4 for w in words) and words <= query:
            found.append((len(words),name,hall,floor))
    if not found: return []
    longest=max(row[0] for row in found)
    return [row[1:] for row in found if row[0]==longest][:4]

def company_reply(message,lang):
    matches=company_matches(message)
    if not matches:return None
    if lang=='en':
        parts=[f'{name}: hall {hall}, floor {floor}.' if hall and floor else f'{name}: the hall is not published.' for name,hall,floor in matches]
        return 'According to the website list checked on 2026-11-08: '+' '.join(parts)+' Stand numbers are not confirmed here. Current list: https://agravia.org/participants.'
    parts=[f'{name}: зал {hall}, этаж {floor}.' if hall and floor else f'{name}: зал пока не указан.' for name,hall,floor in matches]
    return 'По списку сайта, проверенному 08.11.2026: '+' '.join(parts)+' Номер стенда здесь не подтверждён. Актуальный список: https://agravia.org/participants.'

_base_override_intent=override_intent
def override_intent(message,intent,state):
    if intent in {'secrets','pd_request','privacy_delete','privacy_storage'}:return intent
    low=message.lower()
    def has(p):return bool(re.search(p,low))
    if has(r'цен|стоим|стоит|прайс|нацен|тариф|дороже|расцен|price|cost|how much') and has(r'бейдж|пропуск|прр|технич|оборудован|электр|услуг|badge|vehicle pass|technical|equipment'):
        return 'price_manager'
    if has(r'прайс|price list') or (has(r'сколько стоит|how much') and state.get('intent') in {'pass','badge','extra_badge','equipment_in','vehicle_access','price_manager','exhibitor_services'}):
        return 'price_manager'
    if has(r'пропуск|vehicle pass') and has(r'когда.{0,30}(пришл|прид|отправ)|срок.{0,30}(отправ|рассыл)|deadline'):
        return 'pass_deadline'
    if has(r'домашн.{0,15}живот|с собак|с кошк|с питом|поводыр|guide dog|pet|with.{0,10}(dog|cat)'):
        return 'pet_policy'
    if has(r'реб[её]н|дет[ьи]|возраст|0\+|child|under 14|age limit'):
        return 'services_pending' if has(r'монтаж|демонтаж|set.up|dismantl') else 'child_policy'
    if has(r'последн.{0,15}вход|вход.{0,15}закрыти|last (?:entry|admission)'):
        return 'last_entry'
    if has(r'снимать|съ[её]мк|фотограф|штатив|дрон|filming|photograph|drone'):
        return 'photo_policy'
    if has(r'wi.?fi|вай.?фай') and not has(r'стенд|stand'):
        return 'wifi_info'
    if has(r'на ночь|ночн.{0,15}парков|overnight parking'):
        return 'night_parking'
    if has(r'бесплатн.{0,20}консультац|консультац.{0,20}бесплат|free consultation'):
        return 'consult_pending'
    if has(r'открыти|церемони|фуршет|день фермера|день карьеры|opening ceremon|special event'):
        return 'opening_pending'
    if has(r'приложени|назнач.{0,10}встреч|центр компетенц|visitors lounge|бюро наход|камер.{0,10}хранен|маломобиль|коляс|app for|meeting booking|accessibility'):
        return 'services_pending'
    if company_matches(message):return 'catalog'
    return _base_override_intent(message,intent,state)

