_confirmed_override_intent = override_intent
def override_intent(message,intent,state):
    first=_confirmed_override_intent(message,intent,state)
    if first != intent or first in {'secrets','pd_request','privacy_delete','privacy_storage','price_manager','catalog','opening_pending','services_pending','consult_pending'}:return first
    low=message.lower()
    def has(p):return bool(re.search(p,low))
    if has(r'субсиди|господдерж|компенсац.{0,20}участ|subsid|participation support'):return 'subsidy_info'
    if has(r'стать спикер|предлож.{0,15}(спикер|доклад)|выступить.{0,20}выставк|apply.{0,15}speaker'):return 'speaker_apply'
    if has(r'подготов.{0,20}посещ|план.{0,15}визит|чек.?лист|prepare.{0,20}visit'):return 'visitor_plan'
    if has(r'баннер|utm|ролик|пригласить клиентов|banner|invite clients'):return 'promote_exhibitor'
    if intent in {'industry_other','industry_feed','industry_horti','general','other'} and not has(r'зал|стенд|где наход|where is'):
        if has(r'питомник|озелен|ландшафт'):return 'landscape_needs'
        if has(r'картоф|овощ|плод|ягод|теплиц|теплич'):return 'potato_needs'
        if has(r'семен|зерн|полев|сзр'):return 'crop_needs'
        if has(r'корм|ветеринар|лаборатор'):return 'feed_needs'
        if has(r'крс|доени|доиль|птицевод|свиновод|животновод'):return 'livestock_needs'
    return first
